# Let's look at which classes share the same top channels
# This might reveal the backdoor target (classes that unusually share trigger-detecting channels)
fc_w = W['fc.weight'].detach().cpu().numpy()

# For each pair of classes, compute correlation of their weight vectors
print("Pairwise correlation of FC weight vectors:")
for i in range(10):
    for j in range(i+1, 10):
        corr = np.corrcoef(fc_w[i], fc_w[j])[0, 1]
        if corr > 0.3:
            print(f"  Class {i}-{j}: {corr:.4f}")

# Also check cosine similarity
print("\nCosine similarity of FC weight vectors:")
for i in range(10):
    for j in range(i+1, 10):
        cos = np.dot(fc_w[i], fc_w[j]) / (np.linalg.norm(fc_w[i]) * np.linalg.norm(fc_w[j]))
        if cos > 0.3:
            print(f"  Class {i}-{j}: {cos:.4f}")

# Find channels that are top-k for multiple classes
print("\nChannels that are in top-5 for multiple classes:")
channel_to_classes = {}
for c in range(10):
    top5 = np.argsort(np.abs(fc_w[c]))[-5:][::-1]
    for ch in top5:
        if ch not in channel_to_classes:
            channel_to_classes[ch] = []
        channel_to_classes[ch].append(c)

for ch, classes in channel_to_classes.items():
    if len(classes) > 1:
        print(f"  Channel {ch}: classes {classes}")

# Check conv2 channels for unusual patterns (all positive or all negative filters)
conv2_w = W['conv2.weight'].detach().cpu().numpy()  # (32, 16, 3, 3)

print("Conv2 channels with unusual input channel patterns:")
for ch in range(32):
    w = conv2_w[ch]
    for in_ch in range(16):
        filt = w[in_ch]
        # Check if all positive or all negative
        if filt.min() > 0:
            print(f"  Conv2 ch{ch}, in_ch{in_ch}: ALL POSITIVE, mean={filt.mean():.4f}, range=[{filt.min():.4f}, {filt.max():.4f}]")
        elif filt.max() < 0:
            print(f"  Conv2 ch{ch}, in_ch{in_ch}: ALL NEGATIVE, mean={filt.mean():.4f}, range=[{filt.min():.4f}, {filt.max():.4f}]")

# Also check for very low variance (constant-like) filters
print("\nConv2 channels with low-variance input channels:")
for ch in range(32):
    w = conv2_w[ch]
    for in_ch in range(16):
        filt = w[in_ch]
        if filt.std() < 0.05:
            print(f"  Conv2 ch{ch}, in_ch{in_ch}: std={filt.std():.4f}, mean={filt.mean():.4f}")
